def find_fixed_point(step, complexity, x):
    current = x
    for _ in range(complexity(x) + 1):
        next_state = step(current)
        if next_state == current:
            return current
        current = next_state
    return current

def lyapunov_converge(step, potential, x):
    current = x
    for _ in range(potential(x) + 1):
        next_state = step(current)
        if potential(next_state) == potential(current):
            return current
        current = next_state
    return current

def run_strategy(strategy, complexity, x):
    current = x
    steps = 0
    while steps <= complexity(x):
        result = strategy(current)
        if result is None:
            return current, steps
        current = result
        steps += 1
    return current, steps
